const LATEST_PLAN_CACHE_PREFIX="guidance_latest_plan_v1:";
function cacheLatestPlan(plan){
  if(!plan||!plan.id)return;
  try{
    const uid=plan.user_id||state?.user?.id;
    if(!uid)return;
    localStorage.setItem(LATEST_PLAN_CACHE_PREFIX+uid,JSON.stringify({...plan,__cached_at:new Date().toISOString()}));
    try{window.dispatchEvent(new CustomEvent('guidance-plan-updated',{detail:{planId:plan.id}}))}catch(_e){}
    try{const ch=new BroadcastChannel('guidance-smart-reminders');ch.postMessage({type:'plan-updated',planId:plan.id});ch.close()}catch(_e){}
  }catch(_e){}
}

