const state={user:null,account:null,entitlements:[],holidays:[],currentPlan:null,savedPlans:[],editingId:null,editingHolidayId:null,editingWeekIndex:null,planDirty:false};
const el=Object.fromEntries([...document.querySelectorAll('[id]')].map(node=>[node.id,node]));
const $all=(selector,root=document)=>[...root.querySelectorAll(selector)];
function escapeHtml(value){return String(value??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}
function clean(value){return String(value??"").replace(/\s+/g," ").trim()}
function toast(message,error=false){el.toast.textContent=message;el.toast.classList.toggle('error',error);el.toast.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.toast.hidden=true,3600)}
function showStatus(message,error=false){el.planStatus.hidden=false;el.planStatus.textContent=message;el.planStatus.classList.toggle('error',error)}
function hideStatus(){el.planStatus.hidden=true}
function parseDate(value){if(!value)return null;if(value instanceof Date)return new Date(value);const raw=String(value);const d=/^\d{4}-\d{2}-\d{2}$/.test(raw)?new Date(`${raw}T12:00:00`):new Date(raw);return Number.isNaN(d.getTime())?null:d}
function isoDate(date){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
function addDays(date,count){const d=new Date(date);d.setDate(d.getDate()+count);return d}
function startOfSundayWeek(date){const d=new Date(date);d.setDate(d.getDate()-d.getDay());return d}
function formatGregorian(value){const d=value instanceof Date?value:parseDate(value);return d?new Intl.DateTimeFormat('ar-SA',{weekday:'long',day:'numeric',month:'numeric',year:'numeric'}).format(d):'—'}
function formatGregorianShort(value){const d=value instanceof Date?value:parseDate(value);return d?new Intl.DateTimeFormat('ar-SA',{day:'numeric',month:'numeric',year:'numeric'}).format(d):'—'}
function formatHijri(value){const d=value instanceof Date?value:parseDate(value);if(!d)return'—';try{return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura',{day:'numeric',month:'numeric',year:'numeric'}).format(d)}catch(_){return''}}
function formatBoth(value){return `${formatGregorianShort(value)} م${formatHijri(value)?` — ${formatHijri(value)} هـ`:''}`}
function activeEntitlements(){return(state.entitlements||[]).filter(item=>item.is_active!==false&&item.expires_at&&new Date(item.expires_at).getTime()>Date.now())}
function isAdmin(){return Boolean(state.account?.is_system_admin)}
function hasAccess(code){if(SCHOOL_EDITION)return true;const active=activeEntitlements();if(isAdmin())return true;if(code==='messages_library')return active.some(item=>item.billing_period==='yearly');return active.some(item=>item.product_code==='all_access'||item.product_code===code)}
function unifiedLaunchKey(code){return`unified_platform_launch_${code}`}
function rememberUnifiedLaunch(code){try{sessionStorage.setItem(unifiedLaunchKey(code),String(Date.now()));sessionStorage.setItem('unified_last_platform',code)}catch(_){}}
function clearUnifiedLaunches(){try{Object.keys(sessionStorage).filter(key=>key.startsWith('unified_platform_launch_')).forEach(key=>sessionStorage.removeItem(key));sessionStorage.removeItem('unified_last_platform')}catch(_){}}
function cameFromUnifiedPortal(){const params=new URLSearchParams(location.search);const fromPortal=params.get('from')==='portal';let remembered=false;try{remembered=Boolean(sessionStorage.getItem(unifiedLaunchKey(CURRENT_PACKAGE_CODE)))}catch(_){}if(fromPortal){rememberUnifiedLaunch(CURRENT_PACKAGE_CODE);params.delete('from');history.replaceState({},'',location.pathname+(params.toString()?`?${params}`:''));return true}return remembered}
function redirectToPortal(notice='choose_platform'){try{sessionStorage.setItem('portal_notice',notice==='package_locked'?'منصة خطة الموجه الطلابي غير مشمولة في باقتك الحالية.':'اختر المنصة من بوابة المنصات.')}catch(_){}location.replace(`../index.html?notice=${notice}`)}
function goToUnifiedPlatform(code){const item=UNIFIED_PLATFORM_ROUTES[code];if(!item||item.coming||!hasAccess(code))return;rememberUnifiedLaunch(code);location.href=`${item.href}?from=portal`}
function planMeta(){const active=activeEntitlements();if(isAdmin())return{label:'مدير النظام',detail:'صلاحية كاملة لجميع المنصات'};const all=active.find(x=>x.product_code==='all_access');if(all)return{label:'الباقة الشاملة',detail:`سارية حتى ${formatGregorianShort(all.expires_at)}`};const mine=active.find(x=>x.product_code===CURRENT_PACKAGE_CODE);return mine?{label:PACKAGE_LABELS[CURRENT_PACKAGE_CODE],detail:`سارية حتى ${formatGregorianShort(mine.expires_at)}`}:{label:'حساب غير مشترك',detail:'لا توجد باقة نشطة'}}
function renderPlatformSwitcher(){const meta=planMeta();el.platformSwitcher.innerHTML=Object.entries(UNIFIED_PLATFORM_ROUTES).filter(([code])=>code!=="messages_library").map(([code,item])=>{const icon=UNIFIED_PLATFORM_ICONS[code]||'';if(item.coming)return`<span class="platform-tab coming"><span class="platform-tab-icon">${icon}</span><span><strong>${item.label}</strong><small>قريبًا</small></span></span>`;if(!hasAccess(code))return`<span class="platform-tab locked"><span class="platform-tab-icon">${icon}</span><span><strong>${item.label}</strong><small>غير مفعّلة</small></span></span>`;const current=code===CURRENT_PACKAGE_CODE;return`<a href="${item.href}?from=portal" data-platform="${code}" class="platform-tab${current?' current':''}"><span class="platform-tab-icon">${icon}</span><span><strong>${item.label}</strong><small>${current?'المنصة الحالية':'انتقال'}</small></span></a>`}).join('');el.platformPlanBadge.innerHTML=`<span class="plan-dot"></span><span><small>الباقة الحالية</small><strong>${escapeHtml(meta.label)}</strong><em>${escapeHtml(meta.detail)}</em></span>`;el.unifiedPlatformBar.hidden=false;$all('[data-platform]',el.platformSwitcher).forEach(link=>link.onclick=e=>{e.preventDefault();goToUnifiedPlatform(link.dataset.platform)})}
function renderIdentity(){const ctx=window.MishkatSchoolContext?.getContext?.()||{};const school=ctx.schoolName||state.account?.school_name||'اسم المدرسة';const user=ctx.counselorName||state.account?.full_name||state.user?.email||'الموجه الطلابي';el.schoolName.textContent=school;el.userName.textContent=user;el.counselorName.value=user;el.principalName.value=ctx.managerName||el.principalName.value||'';const logo=state.account?.school_logo_data;if(logo){el.schoolLogo.src=logo;el.schoolLogo.hidden=false;el.schoolLogoPlaceholder.hidden=true}else{el.schoolLogo.hidden=true;el.schoolLogoPlaceholder.hidden=false;el.schoolLogoPlaceholder.textContent=school.trim().charAt(0)||'م'}}

function holidayCovers(date,holiday){const value=isoDate(date);return value>=holiday.start&&value<=holiday.end}
function overlappingHolidays(days){return state.holidays.filter(h=>days.some(day=>holidayCovers(day,h)))}
function buildCalendarSegments(start,end){let cursor=startOfSundayWeek(start);const raw=[];let weekNumber=0;while(cursor<=end){const workDays=[0,1,2,3,4].map(i=>addDays(cursor,i)).filter(day=>day>=start&&day<=end);if(workDays.length){const holidays=overlappingHolidays(workDays);const activeDays=workDays.filter(day=>!holidays.some(h=>holidayCovers(day,h)));if(activeDays.length){weekNumber++;raw.push({type:'week',number:weekNumber,start:isoDate(activeDays[0]),end:isoDate(activeDays.at(-1)),calendarStart:isoDate(workDays[0]),calendarEnd:isoDate(workDays.at(-1)),holidays:holidays.map(h=>({...h}))})}else{raw.push({type:'holiday',start:isoDate(workDays[0]),end:isoDate(workDays.at(-1)),holidays:holidays.map(h=>({...h}))})}}cursor=addDays(cursor,7)}const merged=[];raw.forEach(segment=>{const prev=merged.at(-1);if(segment.type==='holiday'&&prev?.type==='holiday'&&Math.round((parseDate(segment.start)-parseDate(prev.end))/86400000)<=7){prev.end=segment.end;const map=new Map([...prev.holidays,...segment.holidays].map(h=>[h.id,h]));prev.holidays=[...map.values()]}else merged.push(segment)});return merged}
function weekOrdinal(number){return WEEK_ORDINALS[number-1]||String(number)}
function stagePrograms(stageKey,weekNumber,totalWeeks){const data=STAGES[stageKey];if(weekNumber===totalWeeks)return["متابعة اختبارات نهاية الفصل الدراسي","تقويم الخطة وتوثيق الإنجازات والتوصيات"];if(weekNumber===totalWeeks-1)return["التهيئة النفسية للاختبارات","متابعة الطلاب أثناء الاختبارات"];return data.programs[(weekNumber-1)%data.programs.length]||["برنامج إرشادي حسب الاحتياج","متابعة تنفيذ الخطة"]}
function makeIntroduction(form){const stage=STAGES[form.stage];return`انطلاقًا من رسالة ${form.schoolName||'المدرسة'} في توفير بيئة تعليمية آمنة وداعمة، أعدّ ${form.counselorName||'الموجه الطلابي'} هذه الخطة لتنظيم الأعمال والخدمات والبرامج الموجهة إلى ${stage.audience} خلال ${form.termName} من العام الدراسي ${form.academicYear||'الحالي'}. وقد بُنيت الخطة على التقويم الدراسي الذي يبدأ في ${formatGregorian(form.startDate)} وينتهي في ${formatGregorian(form.endDate)}، مع مراعاة الإجازات والفواصل الدراسية المدخلة. وتركز الخطة في هذه المرحلة على ${stage.focus} كما تتيح متابعة التنفيذ أسبوعيًا، وتوثيق الأعمال المستجدة، والجلسات الفردية، ودراسات الحالة، والإرشاد الجمعي وفق الاحتياج والإمكانات المتاحة.`}
function currentForm(){const ctx=window.MishkatSchoolContext?.getContext?.()||{};return{title:clean(el.planTitle.value)||'خطة الأعمال الأسبوعية للموجه الطلابي',stage:el.schoolStage.value,termName:ctx.term||el.termName.value,academicYear:ctx.academicYear||clean(el.academicYear.value),counselorName:ctx.counselorName||clean(el.counselorName.value),principalName:ctx.managerName||clean(el.principalName.value),schoolName:ctx.schoolName||state.account?.school_name||'اسم المدرسة',startDate:el.studyStart.value,endDate:el.studyEnd.value}}
function validateForm(form){if(!form.startDate||!form.endDate)return'أدخل تاريخ بداية الدراسة ونهايتها.';if(parseDate(form.endDate)<parseDate(form.startDate))return'تاريخ نهاية الدراسة يجب أن يكون بعد تاريخ البداية.';if(!form.counselorName)return'تعذر تحديد اسم الموجه تلقائيًا من بيانات المستخدم.';if(!form.academicYear)return'اكتب العام الدراسي.';return''}
function resetHolidayEditor(){state.editingHolidayId=null;el.holidayType.value='term';el.holidayTitle.value='';el.holidayStart.value='';el.holidayEnd.value='';el.addHolidayButton.textContent='إضافة الإجازة';el.cancelHolidayEditButton.hidden=true}
function editHoliday(id){const holiday=state.holidays.find(item=>item.id===id);if(!holiday)return;state.editingHolidayId=id;el.holidayType.value=holiday.type;el.holidayTitle.value=holiday.title;el.holidayStart.value=holiday.start;el.holidayEnd.value=holiday.end;el.addHolidayButton.textContent='حفظ تعديل الإجازة';el.cancelHolidayEditButton.hidden=false;el.holidayTitle.focus();document.querySelector('.holidays-panel')?.scrollIntoView({behavior:'smooth',block:'center'})}
function calendarSegmentKey(segment){return segment.type==='week'?`week:${segment.calendarStart||segment.start}`:`holiday:${segment.start}:${segment.end}`}
function normalizeWeekSegment(segment){if(segment.type!=='week')return segment;segment.tasks=(Array.isArray(segment.tasks)?segment.tasks:[]).map(item=>({text:item.text||'',note:item.note||'',fixed:Boolean(item.fixed),done:Boolean(item.done),notDone:Boolean(item.notDone)}));segment.programs=(Array.isArray(segment.programs)?segment.programs:[]).map(item=>typeof item==='string'?{text:item,done:false,notDone:false}:{text:item.text||'',done:Boolean(item.done),notDone:Boolean(item.notDone)});segment.emerging=(Array.isArray(segment.emerging)?segment.emerging:[]).map(item=>({text:item.text||'',done:Boolean(item.done),notDone:Boolean(item.notDone)}));segment.special=segment.special||{individual:false,caseStudy:false,group:false,notes:['','','']};segment.special.notes=Array.isArray(segment.special.notes)?segment.special.notes:['','',''];return segment}
function rebuildCalendarPreservingWork(){if(!state.currentPlan)return;collectEdits();const form=currentForm();const error=validateForm(form);if(error)return showStatus(error,true);const oldWeeks=new Map(state.currentPlan.segments.filter(s=>s.type==='week').map(s=>[calendarSegmentKey(s),normalizeWeekSegment(s)]));const segments=buildCalendarSegments(parseDate(form.startDate),parseDate(form.endDate));const totalWeeks=segments.filter(s=>s.type==='week').length;if(!totalWeeks)return showStatus('لم ينتج عن التقويم أي أسبوع دراسي فعلي.',true);const rebuilt=segments.map(segment=>{if(segment.type!=='week')return segment;const old=oldWeeks.get(calendarSegmentKey(segment));if(old)return normalizeWeekSegment({...old,...segment,number:segment.number,holidays:segment.holidays});return makeWeekData(segment,form,totalWeeks)});state.currentPlan={...state.currentPlan,form,holidays:JSON.parse(JSON.stringify(state.holidays)),segments:rebuilt,introduction:makeIntroduction(form)};state.planDirty=true;renderPlan();el.generatedWeekCount.textContent=totalWeeks;el.savePlanButton.disabled=false;el.printPlanButton.disabled=false;el.planPreviewSection.hidden=false;hideStatus();toast('تم تحديث توزيع الأسابيع مع الاحتفاظ بما أمكن من التنفيذ والتعديلات.')}
function addHoliday(){const title=clean(el.holidayTitle.value),start=el.holidayStart.value,end=el.holidayEnd.value;if(!title||!start||!end)return toast('اكتب اسم الإجازة وتاريخ بدايتها ونهايتها.',true);if(end<start)return toast('نهاية الإجازة يجب أن تكون بعد بدايتها.',true);if(state.editingHolidayId){const index=state.holidays.findIndex(h=>h.id===state.editingHolidayId);if(index>=0)state.holidays[index]={...state.holidays[index],type:el.holidayType.value,title,start,end};toast('تم تعديل الإجازة والتواريخ.')}else{state.holidays.push({id:crypto.randomUUID(),type:el.holidayType.value,title,start,end});toast('تمت إضافة الإجازة.')}state.holidays.sort((a,b)=>a.start.localeCompare(b.start));resetHolidayEditor();renderHolidays();if(state.currentPlan)rebuildCalendarPreservingWork()}
function renderHolidays(){el.holidayCount.textContent=state.holidays.length;el.holidayList.innerHTML=state.holidays.length?state.holidays.map(h=>`<article class="holiday-item"><div><span>${escapeHtml(HOLIDAY_TYPES[h.type]||h.type)}</span><strong>${escapeHtml(h.title)}</strong><small>${formatBoth(h.start)} — ${formatBoth(h.end)}</small></div><div class="holiday-item-actions"><button class="edit" data-edit-holiday="${h.id}" type="button">تعديل</button><button data-delete-holiday="${h.id}" type="button">حذف</button></div></article>`).join(''):'<div class="empty-inline">لم تتم إضافة إجازات بعد.</div>';$all('[data-edit-holiday]',el.holidayList).forEach(b=>b.onclick=()=>editHoliday(b.dataset.editHoliday));$all('[data-delete-holiday]',el.holidayList).forEach(b=>b.onclick=()=>{if(!confirm('حذف هذه الإجازة من التقويم؟'))return;state.holidays=state.holidays.filter(h=>h.id!==b.dataset.deleteHoliday);if(state.editingHolidayId===b.dataset.deleteHoliday)resetHolidayEditor();renderHolidays();if(state.currentPlan)rebuildCalendarPreservingWork()})}
function makeWeekData(segment,form,totalWeeks){const stage=STAGES[form.stage];const tasks=[...COMMON_TASKS,...stage.extras];return{...segment,tasks:tasks.slice(0,8).map((text,index)=>({text,done:false,notDone:false,note:'',fixed:index<4})),programs:stagePrograms(form.stage,segment.number,totalWeeks).map(text=>({text,done:false,notDone:false})),weekNote:segment.holidays.length?`يتضمن هذا الأسبوع: ${segment.holidays.map(h=>h.title).join('، ')}.`:'البرامج الإرشادية تنفذ حسب الخطط المعتمدة والإمكانات والاحتياجات الفعلية.',special:{individual:false,caseStudy:false,group:false,notes:['','','']},emerging:[{text:'',done:false,notDone:false},{text:'',done:false,notDone:false},{text:'',done:false,notDone:false},{text:'',done:false,notDone:false}]}}

function trackableItems(segment){if(segment.type!=='week')return[];const items=[];(segment.tasks||[]).forEach((item,index)=>{if(clean(item.text))items.push({kind:'task',index,...item})});(segment.programs||[]).forEach((item,index)=>{if(clean(item.text))items.push({kind:'program',index,...item})});(segment.emerging||[]).forEach((item,index)=>{if(clean(item.text))items.push({kind:'emerging',index,...item})});return items}
function weekProgress(segment){const items=trackableItems(segment);const completed=items.filter(item=>item.done).length;const notCompleted=items.filter(item=>item.notDone).length;const pending=Math.max(0,items.length-completed-notCompleted);return{total:items.length,completed,notCompleted,pending,percent:items.length?Math.round(completed/items.length*100):0}}
function overallProgress(plan=state.currentPlan){const result={total:0,completed:0,notCompleted:0,pending:0,percent:0};if(!plan)return result;(plan.segments||[]).filter(s=>s.type==='week').forEach(segment=>{const p=weekProgress(segment);result.total+=p.total;result.completed+=p.completed;result.notCompleted+=p.notCompleted;result.pending+=p.pending});result.percent=result.total?Math.round(result.completed/result.total*100):0;return result}
function markDirty(){state.planDirty=true;el.savePlanButton.disabled=false}
function enforceExclusive(doneNode,notDoneNode,changedNode){if(changedNode.checked){if(changedNode===doneNode)notDoneNode.checked=false;else doneNode.checked=false}}
function collectWeekFromPage(page){if(!state.currentPlan||!page)return;const idx=Number(page.dataset.segmentIndex);const segment=state.currentPlan.segments[idx];if(!segment||segment.type!=='week')return;$all('tbody tr[data-task-index]',page).forEach(row=>{const task=segment.tasks[Number(row.dataset.taskIndex)];task.text=clean(row.querySelector('.task-text')?.textContent);task.note=clean(row.querySelector('.task-note')?.textContent);task.done=row.querySelector('.task-done').checked;task.notDone=row.querySelector('.task-not-done').checked});$all('[data-program-index]',page).forEach(row=>{const program=segment.programs[Number(row.dataset.programIndex)];program.text=clean(row.querySelector('.program-text')?.textContent);program.done=Boolean(row.querySelector('.program-done')?.checked);program.notDone=Boolean(row.querySelector('.program-not-done')?.checked)});segment.weekNote=clean(page.querySelector('.week-note')?.textContent);segment.special.individual=page.querySelector('.special-individual').checked;segment.special.caseStudy=page.querySelector('.special-case').checked;segment.special.group=page.querySelector('.special-group').checked;$all('[data-special-note-index]',page).forEach(row=>segment.special.notes[Number(row.dataset.specialNoteIndex)]=clean(row.querySelector('.special-note')?.textContent));$all('tbody tr[data-emerging-index]',page).forEach(row=>{const item=segment.emerging[Number(row.dataset.emergingIndex)];item.text=clean(row.querySelector('.emerging-text')?.textContent);item.done=row.querySelector('.emerging-done').checked;item.notDone=row.querySelector('.emerging-not-done').checked})}
function updateProgressUI(){if(!state.currentPlan)return;const overall=overallProgress();el.overallProgressPercent.textContent=`${overall.percent}%`;el.overallProgressBar.style.width=`${overall.percent}%`;el.overallProgressRing.style.setProperty('--progress',`${overall.percent*3.6}deg`);el.progressTotalItems.textContent=overall.total;el.progressCompletedItems.textContent=overall.completed;el.progressNotCompletedItems.textContent=overall.notCompleted;el.progressPendingItems.textContent=overall.pending;el.progressPlanTitle.textContent=state.currentPlan.form.title;$all('.weekly-page',el.planDocument).forEach(page=>{const segment=state.currentPlan.segments[Number(page.dataset.segmentIndex)];const p=weekProgress(segment);const percent=page.querySelector('[data-week-progress-percent]');const bar=page.querySelector('[data-week-progress-bar]');const stats=page.querySelector('[data-week-progress-stats]');if(percent)percent.textContent=`${p.percent}%`;if(bar)bar.style.width=`${p.percent}%`;if(stats)stats.textContent=`نفذ ${p.completed} • لم ينفذ ${p.notCompleted} • متبقي ${p.pending}`});const summary=el.planDocument.querySelector('[data-overall-print-progress]');if(summary)summary.textContent=`${overall.percent}%`;const summaryBar=el.planDocument.querySelector('[data-overall-print-bar]');if(summaryBar)summaryBar.style.width=`${overall.percent}%`;const printTotal=el.planDocument.querySelector('[data-print-total]');if(printTotal)printTotal.textContent=`المخطط: ${overall.total}`;const printCompleted=el.planDocument.querySelector('[data-print-completed]');if(printCompleted)printCompleted.textContent=`المنفذ: ${overall.completed}`;const printNotCompleted=el.planDocument.querySelector('[data-print-not-completed]');if(printNotCompleted)printNotCompleted.textContent=`لم ينفذ: ${overall.notCompleted}`;const printPending=el.planDocument.querySelector('[data-print-pending]');if(printPending)printPending.textContent=`المتبقي: ${overall.pending}`;$all('[data-summary-week-index]',el.planDocument).forEach(card=>{const segment=state.currentPlan.segments[Number(card.dataset.summaryWeekIndex)];const p=weekProgress(segment);card.querySelector('strong').textContent=`${p.percent}%`;card.querySelector('i').style.width=`${p.percent}%`;card.querySelector('small').textContent=`نفذ ${p.completed} من ${p.total}`});renderWeekNavigator();if(state.editingWeekIndex!==null&&!el.weekEditorModal.hidden)updateWeekEditorProgress()}
function renderWeekNavigator(){if(!state.currentPlan)return;el.weekNavigator.innerHTML=state.currentPlan.segments.map((segment,index)=>{if(segment.type!=='week')return'';const p=weekProgress(segment);return`<button class="week-nav-card" data-open-week="${index}" type="button"><span>الأسبوع ${weekOrdinal(segment.number)}</span><strong>${p.percent}%</strong><div><i style="width:${p.percent}%"></i></div><small>${formatGregorianShort(segment.start)} — ${formatGregorianShort(segment.end)}</small><em>${p.completed} منفذ • ${p.notCompleted} غير منفذ • ${p.pending} متبقي</em></button>`}).join('')}
function progressSummaryPage(plan){const overall=overallProgress(plan);const cards=plan.segments.map((segment,index)=>segment.type==='week'?`<article class="print-progress-week" data-summary-week-index="${index}"><span>الأسبوع ${weekOrdinal(segment.number)}</span><strong>${weekProgress(segment).percent}%</strong><div><i style="width:${weekProgress(segment).percent}%"></i></div><small>نفذ ${weekProgress(segment).completed} من ${weekProgress(segment).total}</small></article>`:'').join('');return`<article class="print-page progress-summary-page"><header>${planHeaderMarkup(plan.form)}</header><div class="print-progress-head"><span>المتابعة الإلكترونية</span><h2>ملخص إنجاز الخطة</h2><p>يعكس هذا الملخص الحالات المحددة داخل الخطة الإلكترونية وقت الطباعة.</p></div><section class="print-progress-overall"><div><span>نسبة الإنجاز الكلية</span><strong data-overall-print-progress>${overall.percent}%</strong></div><div class="print-progress-main-bar"><i data-overall-print-bar style="width:${overall.percent}%"></i></div><div class="print-progress-stats"><b data-print-total>المخطط: ${overall.total}</b><b data-print-completed>المنفذ: ${overall.completed}</b><b data-print-not-completed>لم ينفذ: ${overall.notCompleted}</b><b data-print-pending>المتبقي: ${overall.pending}</b></div></section><section class="print-progress-weeks">${cards}</section></article>`}
function statusSelect(value,cls){return`<select class="${cls}"><option value="pending" ${!value.done&&!value.notDone?'selected':''}>قيد الانتظار</option><option value="done" ${value.done?'selected':''}>نفذ</option><option value="not_done" ${value.notDone?'selected':''}>لم ينفذ</option></select>`}
function openWeekEditor(index){collectEdits();const segment=state.currentPlan?.segments[index];if(!segment||segment.type!=='week')return;state.editingWeekIndex=index;el.weekEditorTitle.textContent=`تعديل الأسبوع ${weekOrdinal(segment.number)}`;el.weekEditorDates.textContent=`${formatGregorian(segment.start)} إلى ${formatGregorian(segment.end)}`;el.weekEditorStart.value=segment.start;el.weekEditorEnd.value=segment.end;el.weekEditorTasks.innerHTML=segment.tasks.map((task,i)=>`<div class="week-editor-row" data-editor-task-index="${i}" data-fixed="${task.fixed?'1':'0'}"><div class="editor-row-main"><input class="editor-task-text" type="text" value="${escapeHtml(task.text)}"><input class="editor-task-note" type="text" value="${escapeHtml(task.note||'')}" placeholder="ملاحظات"></div>${statusSelect(task,'editor-task-status')}<button class="remove-editor-row" data-remove-editor-task="${i}" type="button">×</button></div>`).join('');el.weekEditorPrograms.innerHTML=segment.programs.map((program,i)=>`<div class="week-editor-row" data-editor-program-index="${i}"><input class="editor-program-text" type="text" value="${escapeHtml(program.text)}">${statusSelect(program,'editor-program-status')}<button class="remove-editor-row" data-remove-editor-program="${i}" type="button">×</button></div>`).join('');el.weekEditorNote.value=segment.weekNote||'';el.weekEditorIndividual.checked=Boolean(segment.special.individual);el.weekEditorCaseStudy.checked=Boolean(segment.special.caseStudy);el.weekEditorGroup.checked=Boolean(segment.special.group);el.weekEditorSpecialNotes.value=(segment.special.notes||[]).filter(Boolean).join('\n');el.weekEditorEmerging.innerHTML=segment.emerging.map((item,i)=>`<div class="week-editor-row" data-editor-emerging-index="${i}"><input class="editor-emerging-text" type="text" value="${escapeHtml(item.text)}" placeholder="عمل مستجد">${statusSelect(item,'editor-emerging-status')}<button class="remove-editor-row" data-remove-editor-emerging="${i}" type="button">×</button></div>`).join('');el.weekEditorModal.hidden=false;document.body.style.overflow='hidden';updateWeekEditorProgress()}
function closeWeekEditor(){el.weekEditorModal.hidden=true;document.body.style.overflow='';state.editingWeekIndex=null}
function editorStatusObject(value){return{done:value==='done',notDone:value==='not_done'}}
function readWeekEditorIntoState(){const segment=state.currentPlan?.segments[state.editingWeekIndex];if(!segment)return null;const start=el.weekEditorStart.value,end=el.weekEditorEnd.value;if(!start||!end||end<start){toast('راجع تاريخ بداية الأسبوع ونهايته.',true);return null}segment.start=start;segment.end=end;segment.tasks=$all('[data-editor-task-index]',el.weekEditorTasks).map(row=>{const status=editorStatusObject(row.querySelector('.editor-task-status').value);return{text:clean(row.querySelector('.editor-task-text').value),note:clean(row.querySelector('.editor-task-note').value),fixed:row.dataset.fixed==='1',...status}}).filter(item=>item.text);segment.programs=$all('[data-editor-program-index]',el.weekEditorPrograms).map(row=>{const status=editorStatusObject(row.querySelector('.editor-program-status').value);return{text:clean(row.querySelector('.editor-program-text').value),...status}}).filter(item=>item.text);segment.weekNote=clean(el.weekEditorNote.value);segment.special={individual:el.weekEditorIndividual.checked,caseStudy:el.weekEditorCaseStudy.checked,group:el.weekEditorGroup.checked,notes:el.weekEditorSpecialNotes.value.split(/\n+/).map(clean).filter(Boolean)};while(segment.special.notes.length<3)segment.special.notes.push('');segment.emerging=$all('[data-editor-emerging-index]',el.weekEditorEmerging).map(row=>{const status=editorStatusObject(row.querySelector('.editor-emerging-status').value);return{text:clean(row.querySelector('.editor-emerging-text').value),...status}}).filter(item=>item.text);while(segment.emerging.length<4)segment.emerging.push({text:'',done:false,notDone:false});return segment}
function saveWeekEdits(){const segment=readWeekEditorIntoState();if(!segment)return;markDirty();closeWeekEditor();renderPlan();toast(`تم حفظ تعديلات الأسبوع ${weekOrdinal(segment.number)} داخل الخطة الإلكترونية.`)}
function updateWeekEditorProgress(){if(state.editingWeekIndex===null)return;const segment=state.currentPlan?.segments[state.editingWeekIndex];if(!segment)return;const clone=JSON.parse(JSON.stringify(segment));clone.tasks=$all('[data-editor-task-index]',el.weekEditorTasks).map(row=>({text:row.querySelector('.editor-task-text').value,...editorStatusObject(row.querySelector('.editor-task-status').value)}));clone.programs=$all('[data-editor-program-index]',el.weekEditorPrograms).map(row=>({text:row.querySelector('.editor-program-text').value,...editorStatusObject(row.querySelector('.editor-program-status').value)}));clone.emerging=$all('[data-editor-emerging-index]',el.weekEditorEmerging).map(row=>({text:row.querySelector('.editor-emerging-text').value,...editorStatusObject(row.querySelector('.editor-emerging-status').value)}));const p=weekProgress(clone);el.weekEditorProgressPercent.textContent=`${p.percent}%`;el.weekEditorProgressBar.style.width=`${p.percent}%`}
function addEditorRow(kind){if(kind==='task'){el.weekEditorTasks.insertAdjacentHTML('beforeend',`<div class="week-editor-row" data-editor-task-index="new"><div class="editor-row-main"><input class="editor-task-text" type="text" placeholder="اكتب العمل"><input class="editor-task-note" type="text" placeholder="ملاحظات"></div>${statusSelect({done:false,notDone:false},'editor-task-status')}<button class="remove-editor-row" data-remove-editor-task="new" type="button">×</button></div>`)}else if(kind==='program'){el.weekEditorPrograms.insertAdjacentHTML('beforeend',`<div class="week-editor-row" data-editor-program-index="new"><input class="editor-program-text" type="text" placeholder="اسم البرنامج">${statusSelect({done:false,notDone:false},'editor-program-status')}<button class="remove-editor-row" data-remove-editor-program="new" type="button">×</button></div>`)}else{el.weekEditorEmerging.insertAdjacentHTML('beforeend',`<div class="week-editor-row" data-editor-emerging-index="new"><input class="editor-emerging-text" type="text" placeholder="عمل مستجد">${statusSelect({done:false,notDone:false},'editor-emerging-status')}<button class="remove-editor-row" data-remove-editor-emerging="new" type="button">×</button></div>`)}updateWeekEditorProgress()}

function generatePlan(){const form=currentForm();const error=validateForm(form);if(error)return showStatus(error,true);const segments=buildCalendarSegments(parseDate(form.startDate),parseDate(form.endDate));const totalWeeks=segments.filter(x=>x.type==='week').length;if(!totalWeeks)return showStatus('لم ينتج عن التقويم أي أسبوع دراسي فعلي. راجع التواريخ والإجازات.',true);const introduction=makeIntroduction(form);state.currentPlan={id:state.editingId||null,form,holidays:JSON.parse(JSON.stringify(state.holidays)),introduction,segments:segments.map(s=>s.type==='week'?makeWeekData(s,form,totalWeeks):s),createdAt:new Date().toISOString()};state.planDirty=true;renderPlan();hideStatus();el.savePlanButton.disabled=false;el.printPlanButton.disabled=false;el.planPreviewSection.hidden=false;el.generatedWeekCount.textContent=totalWeeks;el.planPreviewSection.scrollIntoView({behavior:'smooth',block:'start'})}
function logoMarkup(){const logo=state.account?.school_logo_data;return logo?`<img src="${logo}" alt="شعار المدرسة">`:`<span>${escapeHtml((state.account?.school_name||'م').trim().charAt(0)||'م')}</span>`}
function planHeaderMarkup(form){return`<div class="print-brand"><div class="print-logo">${logoMarkup()}</div><div><strong>${escapeHtml(form.schoolName)}</strong><span>التوجيه الطلابي — ${escapeHtml(STAGES[form.stage].label)}</span></div></div><div class="ministry-mark"><b>وزارة التعليم</b><span>خطة الموجه الطلابي</span></div>`}
function coverPage(plan){const f=plan.form;return`<article class="print-page cover-page"><div class="cover-orb orb-a"></div><div class="cover-orb orb-b"></div><header>${planHeaderMarkup(f)}</header><div class="cover-content"><span>خطة تنفيذية مبنية على التقويم الدراسي</span><h1>${escapeHtml(f.title)}</h1><h2>${escapeHtml(STAGES[f.stage].label)}</h2><div class="cover-dates"><b>${escapeHtml(f.termName)}</b><strong>${escapeHtml(f.academicYear)}</strong></div></div><div class="cover-footer"><div><span>الموجه الطلابي</span><strong>${escapeHtml(f.counselorName)}</strong></div><div><span>مدير المدرسة</span><strong>${escapeHtml(f.principalName||'—')}</strong></div></div></article>`}
function introPage(plan){const f=plan.form;return`<article class="print-page intro-page"><header>${planHeaderMarkup(f)}</header><div class="intro-content"><span class="page-kicker">تمهيد</span><h2>مقدمة الخطة</h2><div id="planIntroductionEditor" class="editable-intro" contenteditable="true">${escapeHtml(plan.introduction)}</div><div class="calendar-summary"><div><span>بداية الدراسة</span><strong>${formatBoth(f.startDate)}</strong></div><div><span>نهاية الدراسة</span><strong>${formatBoth(f.endDate)}</strong></div><div><span>المرحلة</span><strong>${escapeHtml(STAGES[f.stage].label)}</strong></div><div><span>عدد أسابيع الدراسة</span><strong>${plan.segments.filter(x=>x.type==='week').length} أسبوعًا</strong></div></div><div class="signature-line"><span>الموجه الطلابي</span><strong>${escapeHtml(f.counselorName)}</strong></div></div></article>`}
function editable(value,cls=''){return`<div class="editable-cell ${cls}" contenteditable="true">${escapeHtml(value||'')}</div>`}
function weekPage(segment,plan,index){const f=plan.form;const p=weekProgress(segment);return`<article class="print-page weekly-page" data-segment-index="${index}" data-week-number="${segment.number}"><header class="weekly-header">${planHeaderMarkup(f)}<button class="edit-week-button no-print" data-edit-week="${index}" type="button">تعديل الأسبوع</button></header><div class="week-title"><span>الأسبوع ${weekOrdinal(segment.number)}</span><div><strong>${formatGregorian(segment.start)}</strong><i>إلى</i><strong>${formatGregorian(segment.end)}</strong></div><small>${formatHijri(segment.start)} هـ — ${formatHijri(segment.end)} هـ</small></div><section class="week-progress-strip"><div><span>إنجاز الأسبوع</span><strong data-week-progress-percent>${p.percent}%</strong></div><div class="week-progress-track"><i data-week-progress-bar style="width:${p.percent}%"></i></div><small data-week-progress-stats>نفذ ${p.completed} • لم ينفذ ${p.notCompleted} • متبقي ${p.pending}</small></section><div class="weekly-layout"><section class="tasks-section"><table><thead><tr><th>م</th><th>الأعمال والخدمات</th><th>نفذ</th><th>لم ينفذ</th><th>ملاحظات</th></tr></thead><tbody>${segment.tasks.map((task,i)=>`<tr data-task-index="${i}"><td>${i+1}</td><td>${editable(task.text,'task-text')}${task.fixed?'<small class="fixed-mark">عمل ثابت</small>':''}</td><td><input class="task-done" type="checkbox" ${task.done?'checked':''}></td><td><input class="task-not-done" type="checkbox" ${task.notDone?'checked':''}></td><td>${editable(task.note,'task-note')}</td></tr>`).join('')}</tbody></table></section><aside class="side-sections"><section class="programs-box"><h3>البرامج الإرشادية في هذا الأسبوع</h3>${segment.programs.map((program,i)=>`<div class="program-progress-row" data-program-index="${i}"><div>${editable(program.text,'program-text')}</div><label title="نفذ"><input class="program-done" type="checkbox" ${program.done?'checked':''}>✓</label><label title="لم ينفذ"><input class="program-not-done" type="checkbox" ${program.notDone?'checked':''}>×</label></div>`).join('')}<h4>ملاحظات</h4>${editable(segment.weekNote,'week-note')}</section><section class="special-box"><h3>أعمال التوجيه الخاصة</h3><div class="special-checks"><label><input class="special-individual" type="checkbox" ${segment.special.individual?'checked':''}> جلسة فردية</label><label><input class="special-case" type="checkbox" ${segment.special.caseStudy?'checked':''}> دراسة حالة</label><label><input class="special-group" type="checkbox" ${segment.special.group?'checked':''}> إرشاد جمعي</label></div>${segment.special.notes.map((n,i)=>`<div data-special-note-index="${i}">${editable(n,'special-note')}</div>`).join('')}</section></aside><section class="emerging-section"><table><thead><tr><th>م</th><th>ما يستجد من أعمال وخدمات</th><th>نفذ</th><th>لم ينفذ</th></tr></thead><tbody>${segment.emerging.map((item,i)=>`<tr data-emerging-index="${i}"><td>${i+1}</td><td>${editable(item.text,'emerging-text')}</td><td><input class="emerging-done" type="checkbox" ${item.done?'checked':''}></td><td><input class="emerging-not-done" type="checkbox" ${item.notDone?'checked':''}></td></tr>`).join('')}</tbody></table></section></div><footer class="weekly-footer"><p>◆ أعمال ثابتة يقوم بها الموجه الطلابي يوميًا. ◆ تستخدم الوسائل التقنية والإعلامية المتاحة بعد أخذ الموافقات اللازمة. ◆ برامج مستمرة طوال العام الدراسي.</p><span>${escapeHtml(f.counselorName)} — ${escapeHtml(f.schoolName)}</span></footer></article>`}
function holidayPage(segment,plan,index){const f=plan.form;const titles=segment.holidays.map(h=>h.title).join(' — ')||'إجازة دراسية';return`<article class="print-page holiday-page" data-segment-index="${index}"><header>${planHeaderMarkup(f)}</header><div class="holiday-page-content"><div class="holiday-symbol">☼</div><span>فاصل في التقويم الدراسي</span><h2>${escapeHtml(titles)}</h2><p>${formatBoth(segment.start)} — ${formatBoth(segment.end)}</p><small>لا تحتسب هذه المدة ضمن ترقيم أسابيع الدراسة الفعلية.</small></div></article>`}
function renderPlan(){const plan=state.currentPlan;if(!plan)return;plan.segments=plan.segments.map(normalizeWeekSegment);el.planDocument.innerHTML=coverPage(plan)+introPage(plan)+progressSummaryPage(plan)+plan.segments.map((s,i)=>s.type==='week'?weekPage(s,plan,i):holidayPage(s,plan,i)).join('');const intro=el.planDocument.querySelector('#planIntroductionEditor');if(intro)intro.oninput=()=>{state.currentPlan.introduction=clean(intro.textContent);markDirty()};renderWeekNavigator();updateProgressUI()}
function collectEdits(){if(!state.currentPlan)return;const intro=el.planDocument.querySelector('#planIntroductionEditor');if(intro)state.currentPlan.introduction=clean(intro.textContent);$all('.weekly-page',el.planDocument).forEach(collectWeekFromPage)}
function bubblePlanSummary(row){const Store=window.MishkatBubbleStore;const id=Store?.idOf?.(row)||row?.id||'';let meta={};try{meta=JSON.parse(row?.Notes||row?.notes||'{}')}catch(_e){}const form=meta.form||{};const model={segments:meta.segments||[]};const prog=overallProgress(model);return{id,title:row?.Title||form.title||'خطة الموجه الطلابي',school_stage:form.stage||'',academic_year:form.academicYear||'',term_name:form.termName||'',start_date:form.startDate||'',end_date:form.endDate||'',completion_rate:prog.percent,completed_items:prog.completed,total_items:prog.total,status:row?.Status||'in_progress',updated_at:row?.['Modified Date']||row?.updated_at||'',__bubbleRow:row}}
async function savePlan(){if(!state.currentPlan)return;collectEdits();const progress=overallProgress();el.savePlanButton.disabled=true;try{const p=state.currentPlan;if(SCHOOL_EDITION){const Store=window.MishkatBubbleStore;if(!Store)throw new Error('طبقة Bubble غير جاهزة.');const saved=await Store.savePlanModel({...p,progress},state.editingId||'');const id=Store.idOf(saved);state.editingId=id;state.currentPlan.id=id;state.planDirty=false;const legacy={id,user_id:state.user.id,title:p.form.title,school_stage:p.form.stage,academic_year:p.form.academicYear,term_name:p.form.termName,start_date:p.form.startDate,end_date:p.form.endDate,completion_rate:progress.percent,completed_items:progress.completed,not_completed_items:progress.notCompleted,pending_items:progress.pending,total_items:progress.total,status:progress.percent===100?'completed':'in_progress',holidays:p.holidays,plan_data:{segments:p.segments,form:p.form},updated_at:new Date().toISOString()};cacheLatestPlan(legacy);toast(`تم حفظ الخطة — الإنجاز ${progress.percent}%.`);await loadSavedPlans();return}const payload={user_id:state.user.id,title:p.form.title,school_name:p.form.schoolName,counselor_name:p.form.counselorName,principal_name:p.form.principalName||null,school_stage:p.form.stage,academic_year:p.form.academicYear||null,term_name:p.form.termName,start_date:p.form.startDate,end_date:p.form.endDate,introduction:p.introduction,holidays:p.holidays,plan_data:{segments:p.segments,form:p.form},status:progress.percent===100?'completed':'in_progress',completion_rate:progress.percent,completed_items:progress.completed,not_completed_items:progress.notCompleted,pending_items:progress.pending,total_items:progress.total,last_progress_at:new Date().toISOString()};let result;if(state.editingId){result=await db.from('counselor_plans').update(payload).eq('id',state.editingId).select().single()}else{result=await db.from('counselor_plans').insert(payload).select().single()}if(result.error)throw result.error;state.editingId=result.data.id;state.currentPlan.id=result.data.id;state.planDirty=false;cacheLatestPlan(result.data);toast(`تم حفظ الخطة الإلكترونية — الإنجاز ${progress.percent}%.`);await loadSavedPlans()}catch(error){console.error(error);toast(error.message||'تعذر حفظ الخطة.',true)}finally{el.savePlanButton.disabled=false}}
async function loadSavedPlans(){if(SCHOOL_EDITION){try{const rows=await window.MishkatBubbleStore.listPlans();state.savedPlans=(rows||[]).map(bubblePlanSummary);renderSavedPlans()}catch(error){console.error(error);el.savedPlansList.innerHTML='<div class="status-box error">تعذر تحميل الخطط المحفوظة.</div>'}return}const{data,error}=await db.from('counselor_plans').select('id,title,school_stage,academic_year,term_name,start_date,end_date,completion_rate,completed_items,total_items,status,updated_at').eq('user_id',state.user.id).order('updated_at',{ascending:false});if(error){el.savedPlansList.innerHTML='<div class="status-box error">تعذر تحميل الخطط المحفوظة.</div>';return}state.savedPlans=data||[];renderSavedPlans()}
function renderSavedPlans(){el.savedPlansList.innerHTML=state.savedPlans.length?state.savedPlans.map(p=>`<article class="saved-plan-item"><div class="saved-plan-copy"><span>${escapeHtml(STAGES[p.school_stage]?.label||p.school_stage)}</span><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.term_name||'')} — ${escapeHtml(p.academic_year||'')} — ${formatGregorianShort(p.start_date)} إلى ${formatGregorianShort(p.end_date)}</p><div class="saved-plan-progress"><div><i style="width:${Number(p.completion_rate||0)}%"></i></div><strong>${Math.round(Number(p.completion_rate||0))}%</strong><small>${Number(p.completed_items||0)} من ${Number(p.total_items||0)} عنصر</small></div><small>آخر تعديل: ${formatGregorianShort(p.updated_at)}</small></div><div><button class="secondary-button" data-open-plan="${p.id}" type="button">فتح</button><button class="danger-button" data-delete-plan="${p.id}" type="button">حذف</button></div></article>`).join(''):'<div class="empty-inline">لا توجد خطط محفوظة بعد.</div>';$all('[data-open-plan]',el.savedPlansList).forEach(b=>b.onclick=()=>openSavedPlan(b.dataset.openPlan));$all('[data-delete-plan]',el.savedPlansList).forEach(b=>b.onclick=()=>deleteSavedPlan(b.dataset.deletePlan))}
async function openSavedPlan(id){if(SCHOOL_EDITION){try{const result=await window.MishkatBubbleStore.getPlanModel(id);if(!result?.model)throw new Error('not_found');const meta=result.model;const form=meta.form||{};state.editingId=id;state.holidays=Array.isArray(meta.holidays)?meta.holidays:[];state.currentPlan={id,form,holidays:state.holidays,introduction:meta.introduction||'',segments:(meta.segments||[]).map(normalizeWeekSegment)};state.planDirty=false;el.planTitle.value=form.title||'';if(form.stage)el.schoolStage.value=form.stage;el.academicYear.value=form.academicYear||'';el.termName.value=form.termName||'';el.counselorName.value=form.counselorName||'';el.principalName.value=form.principalName||'';el.studyStart.value=form.startDate||'';el.studyEnd.value=form.endDate||'';resetHolidayEditor();renderHolidays();renderPlan();el.generatedWeekCount.textContent=state.currentPlan.segments.filter(x=>x.type==='week').length;el.planPreviewSection.hidden=false;el.savePlanButton.disabled=false;el.printPlanButton.disabled=false;el.planPreviewSection.scrollIntoView({behavior:'smooth'});return}catch(error){console.error(error);return toast('تعذر فتح الخطة.',true)}}const{data,error}=await db.from('counselor_plans').select('*').eq('id',id).single();if(error)return toast('تعذر فتح الخطة.',true);cacheLatestPlan(data);state.editingId=data.id;state.holidays=Array.isArray(data.holidays)?data.holidays:[];const form=data.plan_data?.form||{title:data.title,stage:data.school_stage,academicYear:data.academic_year,termName:data.term_name,counselorName:data.counselor_name,principalName:data.principal_name,schoolName:data.school_name,startDate:data.start_date,endDate:data.end_date};state.currentPlan={id:data.id,form,holidays:state.holidays,introduction:data.introduction||'',segments:(data.plan_data?.segments||[]).map(normalizeWeekSegment)};state.planDirty=false;el.planTitle.value=form.title;el.schoolStage.value=form.stage;el.academicYear.value=form.academicYear||'';el.termName.value=form.termName||'الفصل الدراسي الأول';el.counselorName.value=form.counselorName||'';el.principalName.value=form.principalName||'';el.studyStart.value=form.startDate;el.studyEnd.value=form.endDate;resetHolidayEditor();renderHolidays();renderPlan();el.generatedWeekCount.textContent=state.currentPlan.segments.filter(x=>x.type==='week').length;el.planPreviewSection.hidden=false;el.savePlanButton.disabled=false;el.printPlanButton.disabled=false;el.planPreviewSection.scrollIntoView({behavior:'smooth'})}
async function deleteSavedPlan(id){if(!confirm('حذف هذه الخطة نهائيًا؟'))return;if(SCHOOL_EDITION){try{await window.MishkatBubbleStore.deletePlanModel(id);if(state.editingId===id)newPlan();toast('تم حذف الخطة.');await loadSavedPlans()}catch(error){console.error(error);toast('تعذر حذف الخطة.',true)}return}const{error}=await db.from('counselor_plans').delete().eq('id',id);if(error)return toast('تعذر حذف الخطة.',true);if(state.editingId===id)newPlan();toast('تم حذف الخطة.');await loadSavedPlans()}
function newPlan(){state.editingId=null;state.editingWeekIndex=null;state.currentPlan=null;state.holidays=[];state.planDirty=false;el.planPreviewSection.hidden=true;el.planDocument.innerHTML='';el.weekNavigator.innerHTML='';el.savePlanButton.disabled=true;el.printPlanButton.disabled=true;{const ctx=window.MishkatSchoolContext?.getContext?.()||{};el.planTitle.value=ctx.schoolType==='girls'?'خطة الأعمال الأسبوعية للموجهة الطلابية':'خطة الأعمال الأسبوعية للموجه الطلابي';window.MishkatSchoolContext?.applyDocument?.(document);if(ctx.term)el.termName.value=ctx.term;if(ctx.academicYear)el.academicYear.value=ctx.academicYear;if(ctx.managerName)el.principalName.value=ctx.managerName;}el.studyStart.value='';el.studyEnd.value='';resetHolidayEditor();renderHolidays();hideStatus();window.scrollTo({top:0,behavior:'smooth'})}
function printPlan(){if(!state.currentPlan)return;collectEdits();updateProgressUI();document.body.classList.add('printing-plan');window.print()}
async function loadAccount(){let{data,error}=await db.from('premium_accounts').select('user_id,full_name,email,school_name,school_logo_data,is_system_admin,is_active').eq('user_id',state.user.id).single();if(error)throw error;state.account=data;const result=await db.from('premium_entitlements').select('id,user_id,product_code,billing_period,expires_at,is_active').eq('user_id',state.user.id).order('expires_at',{ascending:false});if(result.error)throw result.error;state.entitlements=result.data||[]}
async function init(){
  if(SCHOOL_EDITION){const ctx=window.MishkatSchoolContext?.getContext?.()||{};state.user={id:ctx.id||"mishkat-school-user",email:""};state.account={user_id:state.user.id,full_name:ctx.counselorName||"الموجه الطلابي",school_name:ctx.schoolName||"مدارس المشكاة الأهلية",school_logo_data:"../assets/school-logo.png",is_system_admin:false,is_active:true};state.entitlements=[];renderPlatformSwitcher();renderIdentity();el.accessGate.hidden=true;el.appShell.hidden=false;state.savedPlans=[];renderSavedPlans();newPlan();await loadSavedPlans();return;}const{data:{session}}=await db.auth.getSession();if(!session)return redirectToPortal('choose_platform');state.user=session.user;try{await loadAccount();if(state.account?.is_active===false)throw new Error('هذا الحساب موقوف.');if(!hasAccess(CURRENT_PACKAGE_CODE))return redirectToPortal('package_locked');if(!cameFromUnifiedPortal())return redirectToPortal('choose_platform');renderPlatformSwitcher();renderIdentity();el.accessGate.hidden=true;el.appShell.hidden=false;await loadSavedPlans()}catch(error){el.accessGate.innerHTML=`<div class="gate-error"><strong>تعذر فتح المنصة</strong><p>${escapeHtml(error.message||'حدث خطأ غير متوقع.')}</p><a href="../index.html">العودة إلى البوابة</a></div>`}}
function bind(){el.addHolidayButton.onclick=addHoliday;el.cancelHolidayEditButton.onclick=resetHolidayEditor;el.generatePlanButton.onclick=generatePlan;el.savePlanButton.onclick=savePlan;el.printPlanButton.onclick=printPlan;el.newPlanButton.onclick=newPlan;el.refreshPlansButton.onclick=loadSavedPlans;el.addWeekTaskButton.onclick=()=>addEditorRow('task');el.addWeekProgramButton.onclick=()=>addEditorRow('program');el.addEmergingTaskButton.onclick=()=>addEditorRow('emerging');el.saveWeekEditsButton.onclick=saveWeekEdits;$all('[data-close-week-editor]').forEach(node=>node.onclick=closeWeekEditor);el.weekNavigator.addEventListener('click',event=>{const button=event.target.closest('[data-open-week]');if(button)openWeekEditor(Number(button.dataset.openWeek))});el.planDocument.addEventListener('click',event=>{const edit=event.target.closest('[data-edit-week]');if(edit){event.preventDefault();openWeekEditor(Number(edit.dataset.editWeek))}});el.planDocument.addEventListener('change',event=>{const page=event.target.closest('.weekly-page');if(!page)return;if(event.target.matches('.task-done,.task-not-done')){const row=event.target.closest('[data-task-index]');enforceExclusive(row.querySelector('.task-done'),row.querySelector('.task-not-done'),event.target)}if(event.target.matches('.program-done,.program-not-done')){const row=event.target.closest('[data-program-index]');enforceExclusive(row.querySelector('.program-done'),row.querySelector('.program-not-done'),event.target)}if(event.target.matches('.emerging-done,.emerging-not-done')){const row=event.target.closest('[data-emerging-index]');enforceExclusive(row.querySelector('.emerging-done'),row.querySelector('.emerging-not-done'),event.target)}collectWeekFromPage(page);markDirty();updateProgressUI()});el.planDocument.addEventListener('input',event=>{const page=event.target.closest('.weekly-page');if(!page)return;collectWeekFromPage(page);markDirty();updateProgressUI()});el.weekEditorModal.addEventListener('click',event=>{const remove=event.target.closest('[data-remove-editor-task],[data-remove-editor-program],[data-remove-editor-emerging]');if(remove){remove.closest('.week-editor-row').remove();updateWeekEditorProgress()}});el.weekEditorModal.addEventListener('input',updateWeekEditorProgress);el.weekEditorModal.addEventListener('change',updateWeekEditorProgress);[el.studyStart,el.studyEnd].forEach(input=>input.addEventListener('change',()=>{if(state.currentPlan)showStatus('تم تعديل تواريخ الدراسة. اضغط «إنشاء الخطة الآن» لإعادة توزيع الأسابيع مع التقويم الجديد.',false)}));window.addEventListener('afterprint',()=>document.body.classList.remove('printing-plan'));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!el.weekEditorModal.hidden)closeWeekEditor();if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();if(state.currentPlan)savePlan()}})}
bind();init();
